            aWandererF = aWandererF + (((RotL64(aIngress, 13U) + aOrbiterA) + RotL64(aOrbiterE, 11U)) + aNonceWordJ);
            aWandererA = aWandererA ^ ((((RotL64(aScatter, 5U) + aOrbiterB) + RotL64(aOrbiterK, 28U)) + RotL64(aCarry, 5U)) + aWUSaltC[(((511U - aIndex) + 1U)) & S_SALT1]);
            aWandererE = aWandererE + (((RotL64(aPrevious, 34U) + RotL64(aOrbiterE, 23U)) + aOrbiterC) + aWUSaltA[(((511U - aIndex) + 361U)) & S_SALT1]);
            //
            aCarry = aCarry + (aWandererJ ^ RotL64(aWandererC, 30U));
