            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterI = (aWandererD + RotL64(aScatter, 57U)) + 0x86B51CF53919B1A0ULL;
            aOrbiterD = ((aWandererB + RotL64(aPrevious, 13U)) + RotL64(aCarry, 23U)) + 0xA083352BD75606E3ULL;
