            aWandererC = aWandererC ^ (((RotL64(aScatter, 51U) + aOrbiterJ) + RotL64(aOrbiterK, 37U)) + aWUSaltC[((aIndex + 121U)) & S_SALT1]);
            aWandererH = aWandererH + ((RotL64(aPrevious, 11U) + aOrbiterB) + RotL64(aOrbiterE, 47U));
            aWandererJ = aWandererJ ^ ((RotL64(aCross, 60U) + aOrbiterI) + RotL64(aOrbiterJ, 27U));
            aWandererG = aWandererG + ((((RotL64(aIngress, 29U) + RotL64(aOrbiterD, 54U)) + aOrbiterF) + RotL64(aCarry, 27U)) + aWUSaltE[(((511U - aIndex) + 385U)) & S_SALT1]);
